    sys.path.insert(0, os.path.join(SP, "edge26")); import yf
    out = sys.argv[1]; mks = sys.argv[2:] or list(LISTS); got = {}
    for mk in mks:
        d = os.path.join(out, mk); os.makedirs(d, exist_ok=True); got[mk] = []
        for s in LISTS[mk]:
            if os.path.exists(os.path.join(d, (s + SUF[mk]) + ".csv")): continue
            try:
                r = yf.daily(s + SUF[mk], d)
                if r and r.get("rows", 0) >= 500: got[mk].append((s, r["first"], r["rows"]))
            except Exception as e: print(mk, s, "ERR", str(e)[:80], flush=True)
            time.sleep(0.25)
        print(mk, len(got[mk]), "of", len(LISTS[mk]), "fetched with >= 500 rows; earliest", min(x[1] for x in got[mk]) if got[mk] else None, flush=True)
    json.dump(got, open(os.path.join(out, "world_fetched.json"), "w"), indent=1)
